import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.BUS5y9ZA.js";const c=JSON.parse('{"title":"로그인 세션 관리 안내","description":"","frontmatter":{},"headers":[],"relativePath":"manage_session.md","filePath":"manage_session.md"}'),i={name:"manage_session.md"};function d(o,t,h,n,s,p){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="로그인-세션-관리-안내" tabindex="-1">로그인 세션 관리 안내 <a class="header-anchor" href="#로그인-세션-관리-안내" aria-label="Permalink to &quot;로그인 세션 관리 안내&quot;">​</a></h1><h2 id="_1-로그인-방법" tabindex="-1">1. 로그인 방법 <a class="header-anchor" href="#_1-로그인-방법" aria-label="Permalink to &quot;1. 로그인 방법&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>로그인 방법</th></tr></thead><tbody><tr><td>근무자</td><td>이름과 연락처 또는 Passkey로 로그인</td></tr><tr><td>관리자</td><td>등록된 Google 계정으로 로그인</td></tr></tbody></table><p>등록되지 않았거나 이용 권한이 없는 사용자는 로그인할 수 없다.</p><h2 id="_2-로그인은-얼마나-유지되나요" tabindex="-1">2. 로그인은 얼마나 유지되나요? <a class="header-anchor" href="#_2-로그인은-얼마나-유지되나요" aria-label="Permalink to &quot;2. 로그인은 얼마나 유지되나요?&quot;">​</a></h2><p>근무자와 관리자 모두 브라우저나 탭을 닫아도 로그인 상태가 유지된다. 같은 브라우저에서 다시 접속하면 별도의 로그인 없이 이전 화면을 계속 이용할 수 있다.</p><p>로그인 상태에는 정해진 만료 시간을 두지 않는다. 다만 다음 조건이 모두 충족되어야 자동 로그인이 유지된다.</p><ul><li>브라우저에 로그인 정보가 남아 있어야 한다.</li><li>근무자 또는 관리자 권한이 계속 유효해야 한다.</li><li>인증 정보에 보안상 문제가 없어야 한다.</li></ul><p>접속할 때마다 현재 이용 권한을 확인하고, 근무자의 배정 근무지와 근태 정보도 최신 내용으로 갱신한다.</p><h2 id="_3-언제-다시-로그인해야-하나요" tabindex="-1">3. 언제 다시 로그인해야 하나요? <a class="header-anchor" href="#_3-언제-다시-로그인해야-하나요" aria-label="Permalink to &quot;3. 언제 다시 로그인해야 하나요?&quot;">​</a></h2><p>다음과 같은 경우에는 로그인 화면이 다시 나타날 수 있다.</p><ul><li>사용자가 직접 로그아웃한 경우</li><li>브라우저의 쿠키나 사이트 데이터를 삭제한 경우</li><li>시크릿 모드를 종료한 경우</li><li>다른 기기 또는 관리 기능에서 인증이 해제된 경우</li><li>저장된 로그인 정보가 손상되었거나 보안상 사용할 수 없게 된 경우</li></ul><p>인터넷 연결이 일시적으로 끊어진 경우에는 저장된 로그인 정보를 바로 삭제하지 않는다. 연결이 복구되면 다시 접속하여 이용 권한을 확인한다.</p><h2 id="_4-퇴직·삭제·권한-회수-시에는-어떻게-되나요" tabindex="-1">4. 퇴직·삭제·권한 회수 시에는 어떻게 되나요? <a class="header-anchor" href="#_4-퇴직·삭제·권한-회수-시에는-어떻게-되나요" aria-label="Permalink to &quot;4. 퇴직·삭제·권한 회수 시에는 어떻게 되나요?&quot;">​</a></h2><p>로그인 상태가 남아 있어도 현재 이용 권한이 없으면 시스템을 사용할 수 없다.</p><table tabindex="0"><thead><tr><th>상황</th><th>처리 결과</th></tr></thead><tbody><tr><td>근무자가 퇴직 처리되거나 삭제됨</td><td>근무자 화면과 업무 기능 이용 차단</td></tr><tr><td>관리자가 삭제되거나 권한이 회수됨</td><td>관리자 화면과 관리 기능 이용 차단</td></tr><tr><td>권한이 다시 부여됨</td><td>보안을 위해 다시 로그인</td></tr></tbody></table><p>근무자의 경우 이용할 수 없는 상태가 확인되면 저장된 로그인 정보를 지우고 로그인 화면으로 이동한다. 관리자는 등록된 관리자 권한이 확인되지 않으면 관리자 화면에 들어갈 수 없다.</p><h2 id="_5-로그아웃하면-어떻게-되나요" tabindex="-1">5. 로그아웃하면 어떻게 되나요? <a class="header-anchor" href="#_5-로그아웃하면-어떻게-되나요" aria-label="Permalink to &quot;5. 로그아웃하면 어떻게 되나요?&quot;">​</a></h2><p>근무자가 로그아웃하면 저장된 로그인 정보와 알림 연결 정보를 정리한 후 근무자 로그인 화면으로 이동한다.</p><p>관리자가 로그아웃하면 관리자 인증을 종료한 후 관리자 로그인 화면으로 이동한다.</p><p>공용 PC나 다른 사람과 함께 사용하는 기기에서는 브라우저만 닫지 말고 반드시 <strong>로그아웃</strong>해야 한다.</p><h2 id="_6-자동-로그인이-되지-않을-때" tabindex="-1">6. 자동 로그인이 되지 않을 때 <a class="header-anchor" href="#_6-자동-로그인이-되지-않을-때" aria-label="Permalink to &quot;6. 자동 로그인이 되지 않을 때&quot;">​</a></h2><p>다음 사항을 순서대로 확인한다.</p><ol><li>인터넷 연결을 확인하고 다시 접속한다.</li><li>올바른 이름·연락처 또는 등록된 Google 계정을 사용했는지 확인한다.</li><li>브라우저에서 쿠키와 사이트 데이터 저장이 차단되어 있지 않은지 확인한다.</li><li>퇴직, 계정 삭제 또는 권한 회수 여부를 관리자에게 문의한다.</li></ol><p>문제가 계속되면 관리자에게 사용자 이름, 접속 시각 및 화면에 표시된 안내 문구를 전달한다.</p>',25)])])}const b=a(i,[["render",d]]);export{c as __pageData,b as default};
